operation.add:
// SvetLamp filter: attribute name in the shop => address parameter, row title, unit
$sl_groups = array(
	'Мощность лампы' => array('param' => 'power', 'label' => 'Мощность', 'unit' => 'Вт'),
	'Мощность'       => array('param' => 'wt',    'label' => 'Мощность', 'unit' => 'Вт'),
	'Напряжение'     => array('param' => 'volt',  'label' => 'Напряжение', 'unit' => 'В')
);

// The values chosen in each row
$sl_filter = array();

foreach ($sl_groups as $sl_name => $sl_group) {
	if (!empty($this->request->get[$sl_group['param']])) {
		foreach (explode(',', $this->request->get[$sl_group['param']]) as $sl_value) {
			$sl_value = trim($sl_value);

			if ($sl_value !== '' && (!isset($sl_filter[$sl_name]) || !in_array($sl_value, $sl_filter[$sl_name]))) {
				$sl_filter[$sl_name][] = $sl_value;
			}
		}
	}
}

// Sorting and page size stay in the button links, the page number starts again
$sl_url = '';

foreach (array('sort', 'order', 'limit') as $sl_key) {
	if (isset($this->request->get[$sl_key])) {
		$sl_url .= '&' . $sl_key . '=' . $this->request->get[$sl_key];
	}
}

$data['sl_filters'] = array();

foreach ($sl_groups as $sl_name => $sl_group) {
	// Count products under the other rows' choice
	$sl_where = '';

	foreach ($sl_filter as $sl_other => $sl_values) {
		if ($sl_other != $sl_name) {
			$sl_where .= " AND p.product_id IN (SELECT pa2.product_id FROM `" . DB_PREFIX . "product_attribute` pa2 LEFT JOIN `" . DB_PREFIX . "attribute_description` ad2 ON (ad2.attribute_id = pa2.attribute_id AND ad2.language_id = pa2.language_id) WHERE ad2.name = '" . $this->db->escape($sl_other) . "' AND pa2.language_id = '" . (int)$this->config->get('config_language_id') . "' AND pa2.text IN ('" . implode("','", array_map(array($this->db, 'escape'), $sl_values)) . "'))";
		}
	}

	$sl_rows = $this->db->query("SELECT pa.text, COUNT(DISTINCT p.product_id) AS total FROM `" . DB_PREFIX . "product_attribute` pa LEFT JOIN `" . DB_PREFIX . "attribute_description` ad ON (ad.attribute_id = pa.attribute_id AND ad.language_id = pa.language_id) LEFT JOIN `" . DB_PREFIX . "product_to_category` p2c ON (p2c.product_id = pa.product_id) LEFT JOIN `" . DB_PREFIX . "product` p ON (p.product_id = pa.product_id) LEFT JOIN `" . DB_PREFIX . "product_to_store` p2s ON (p2s.product_id = p.product_id) WHERE ad.name = '" . $this->db->escape($sl_name) . "' AND p2c.category_id = '" . (int)$category_id . "' AND pa.language_id = '" . (int)$this->config->get('config_language_id') . "' AND TRIM(pa.text) <> '' AND p.status = '1' AND p.date_available <= NOW() AND p2s.store_id = '" . (int)$this->config->get('config_store_id') . "'" . $sl_where . " GROUP BY pa.text ORDER BY CAST(REPLACE(pa.text, ',', '.') AS DECIMAL(10,2)), pa.text")->rows;

	$sl_chosen = isset($sl_filter[$sl_name]) ? $sl_filter[$sl_name] : array();

	// A row with a single value filters nothing, unless that value is already chosen
	if (count($sl_rows) < 2 && !$sl_chosen) {
		continue;
	}

	$sl_options = array();

	foreach ($sl_rows as $sl_row) {
		$sl_active = in_array($sl_row['text'], $sl_chosen);
		$sl_next = $sl_filter;
		$sl_next[$sl_name] = $sl_active ? array_values(array_diff($sl_chosen, array($sl_row['text']))) : array_merge($sl_chosen, array($sl_row['text']));

		// A bare number gets its unit: «24» → «24 В», «9.5» → «9,5 Вт»; «12V» stays as it is
		$sl_label = str_replace('.', ',', $sl_row['text']);

		if (preg_match('/^[0-9]+([.,][0-9]+)?$/', trim($sl_row['text']))) {
			$sl_label .= ' ' . $sl_group['unit'];
		}

		$sl_options[] = array(
			'name'   => $sl_label,
			'total'  => (int)$sl_row['total'],
			'active' => $sl_active,
			'href'   => $this->url->link('product/category', 'path=' . $this->request->get['path'] . $sl_url . $this->slFilterUrl($sl_groups, $sl_next))
		);
	}

	$sl_next = $sl_filter;
	unset($sl_next[$sl_name]);

	$data['sl_filters'][] = array(
		'label'   => $sl_group['label'],
		'options' => $sl_options,
		'reset'   => $sl_chosen ? $this->url->link('product/category', 'path=' . $this->request->get['path'] . $sl_url . $this->slFilterUrl($sl_groups, $sl_next)) : ''
	);
}

// SvetLamp filter: the address part for the chosen values, «&wt=60,100&volt=24»
private function slFilterUrl($groups, $filter) {
	$url = '';

	foreach ($groups as $name => $group) {
		if (!empty($filter[$name])) {
			$url .= '&' . $group['param'] . '=' . urlencode(implode(',', $filter[$name]));
		}
	}

	return $url;
}

// SvetLamp filter: products having one of the chosen values, for each attribute
if (!empty($data['filter_sl'])) {
	foreach ($data['filter_sl'] as $sl_name => $sl_values) {
		$sl_list = array();

		foreach ($sl_values as $sl_value) {
			$sl_list[] = "'" . $this->db->escape($sl_value) . "'";
		}

		if ($sl_list) {
			$sql .= " AND p.product_id IN (SELECT pa.product_id FROM `" . DB_PREFIX . "product_attribute` pa LEFT JOIN `" . DB_PREFIX . "attribute_description` ad ON (ad.attribute_id = pa.attribute_id AND ad.language_id = pa.language_id) WHERE ad.name = '" . $this->db->escape($sl_name) . "' AND pa.language_id = '" . (int)$this->config->get('config_language_id') . "' AND pa.text IN (" . implode(',', $sl_list) . "))";
		}
	}
}
